{
  "name": "grouped-search-storefront",
  "version": "1.0.0",
  "private": true,
  "description": "Grouped search results storefront powered by Typesense",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

"use strict";

const fs = require("fs");
const path = require("path");

const TYPESENSE_HOST = process.env.TYPESENSE_HOST || "127.0.0.1";
const TYPESENSE_PORT = process.env.TYPESENSE_PORT || "8108";
const TYPESENSE_PROTOCOL = process.env.TYPESENSE_PROTOCOL || "http";
const TYPESENSE_API_KEY_FILE =
  process.env.TYPESENSE_API_KEY_FILE || "/etc/typesense-api-key";

function readApiKey() {
  if (process.env.TYPESENSE_API_KEY) {
    return process.env.TYPESENSE_API_KEY.trim();
  }
  return fs.readFileSync(TYPESENSE_API_KEY_FILE, "utf8").trim();
}

const API_KEY = readApiKey();
const BASE_URL = `${TYPESENSE_PROTOCOL}://${TYPESENSE_HOST}:${TYPESENSE_PORT}`;

const COLLECTION_NAME = "products";
const DATASET_PATH = path.join(__dirname, "..", "data", "products.jsonl");

/**
 * Perform a raw request against the Typesense HTTP API.
 */
async function tsRequest(pathname, { method = "GET", query, body, rawBody } = {}) {
  const url = new URL(BASE_URL + pathname);
  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value === undefined || value === null) continue;
      url.searchParams.set(key, String(value));
    }
  }

  const headers = {
    "X-TYPESENSE-API-KEY": API_KEY,
  };

  let fetchBody;
  if (rawBody !== undefined) {
    fetchBody = rawBody;
    headers["Content-Type"] = "text/plain";
  } else if (body !== undefined) {
    fetchBody = JSON.stringify(body);
    headers["Content-Type"] = "application/json";
  }

  const response = await fetch(url, {
    method,
    headers,
    body: fetchBody,
  });

  const text = await response.text();
  let parsed;
  try {
    parsed = text ? JSON.parse(text) : {};
  } catch (err) {
    parsed = { raw: text };
  }

  if (!response.ok) {
    const err = new Error(
      `Typesense request failed: ${method} ${pathname} -> ${response.status} ${JSON.stringify(
        parsed
      )}`
    );
    err.status = response.status;
    err.body = parsed;
    throw err;
  }

  return parsed;
}

async function collectionExists(name) {
  try {
    await tsRequest(`/collections/${encodeURIComponent(name)}`);
    return true;
  } catch (err) {
    if (err.status === 404) return false;
    throw err;
  }
}

async function createCollection() {
  const schema = {
    name: COLLECTION_NAME,
    fields: [
      { name: "name", type: "string" },
      { name: "brand", type: "string", facet: true },
      { name: "popularity", type: "int32" },
      { name: "price", type: "float" },
    ],
  };

  try {
    await tsRequest("/collections", { method: "POST", body: schema });
  } catch (err) {
    // 409 => already exists (race with another process/startup). Safe to ignore.
    if (err.status !== 409) throw err;
  }
}

async function importDataset() {
  const raw = fs.readFileSync(DATASET_PATH, "utf8");
  // Normalize to plain LF-separated JSON lines, dropping empty trailing lines.
  const lines = raw
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l.length > 0);
  const body = lines.join("\n");

  const result = await tsRequest(
    `/collections/${encodeURIComponent(COLLECTION_NAME)}/documents/import`,
    {
      method: "POST",
      query: { action: "upsert" },
      rawBody: body,
    }
  );

  // The import endpoint returns newline-delimited JSON result objects as text,
  // but our tsRequest tries JSON.parse on the whole thing which will fail for
  // multi-line responses; handle that case here.
  if (result && result.raw) {
    const resultLines = result.raw
      .split(/\r?\n/)
      .map((l) => l.trim())
      .filter(Boolean);
    for (const line of resultLines) {
      let obj;
      try {
        obj = JSON.parse(line);
      } catch (e) {
        continue;
      }
      if (obj && obj.success === false) {
        console.error("Failed to import document:", obj);
      }
    }
  }
}

/**
 * Ensure the `products` collection exists and is loaded with the dataset.
 * Safe to call multiple times (idempotent upsert).
 */
async function ensureCollectionAndData() {
  const exists = await collectionExists(COLLECTION_NAME);
  if (!exists) {
    await createCollection();
  }
  await importDataset();
}

function escapeFilterValue(value) {
  // Wrap in backticks to safely handle commas/special characters per
  // Typesense filter_by string literal syntax.
  return "`" + String(value).replace(/`/g, "") + "`";
}

/**
 * Search the collection, grouping hits by brand.
 * Returns { totalGroups, groups: [{ brand, total, items }] }
 */
async function groupedSearch({ q, page, groupLimit, groupsPerPage }) {
  const query = {
    q: q && q.trim() ? q.trim() : "*",
    query_by: "name",
    group_by: "brand",
    group_limit: groupLimit,
    sort_by: "popularity:desc",
    per_page: groupsPerPage,
    page,
  };

  const data = await tsRequest(
    `/collections/${encodeURIComponent(COLLECTION_NAME)}/documents/search`,
    { query }
  );

  const totalGroups = data.found || 0;
  const groups = (data.grouped_hits || []).map((gh) => ({
    brand: gh.group_key[0],
    total: gh.found,
    items: gh.hits.map((h) => h.document),
  }));

  return { totalGroups, groups };
}

/**
 * Fetch every matching item for a single brand (used to satisfy "show more").
 */
async function fetchAllForBrand({ q, brand }) {
  const query = {
    q: q && q.trim() ? q.trim() : "*",
    query_by: "name",
    filter_by: `brand:=${escapeFilterValue(brand)}`,
    sort_by: "popularity:desc",
    per_page: 250,
    page: 1,
  };

  const data = await tsRequest(
    `/collections/${encodeURIComponent(COLLECTION_NAME)}/documents/search`,
    { query }
  );

  return (data.hits || []).map((h) => h.document);
}

module.exports = {
  ensureCollectionAndData,
  groupedSearch,
  fetchAllForBrand,
  COLLECTION_NAME,
};

"use strict";

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * Build a "/" URL preserving q, page and expand state.
 */
function buildUrl({ q, page, expand }) {
  const params = new URLSearchParams();
  if (q) params.set("q", q);
  params.set("page", String(page));
  for (const brand of expand) {
    params.append("expand", brand);
  }
  const qs = params.toString();
  return qs ? `/?${qs}` : "/";
}

function renderGroup({ q, page, expand, groupLimit, group }) {
  const { brand, total, items } = group;
  const isExpanded = expand.includes(brand);
  const showMoreNeeded = total > groupLimit && !isExpanded;

  const itemsHtml = items
    .map(
      (item) => `
      <li data-testid="item" data-id="${escapeHtml(item.id)}" class="item">
        <span class="item-name">${escapeHtml(item.name)}</span>
        <span class="item-meta">popularity: ${escapeHtml(
          item.popularity
        )} &middot; $${escapeHtml(item.price)}</span>
      </li>`
    )
    .join("");

  let showMoreHtml = "";
  if (showMoreNeeded) {
    const href = buildUrl({ q, page, expand: [...expand, brand] });
    const remaining = total - items.length;
    showMoreHtml = `<a class="show-more" data-testid="show-more" href="${escapeHtml(
      href
    )}">Show more (${remaining} more)</a>`;
  }

  return `
    <section data-testid="group" data-brand="${escapeHtml(
      brand
    )}" data-total="${total}" class="group">
      <h2 class="brand-name">${escapeHtml(brand)}</h2>
      <p class="brand-total">${total} product${
    total === 1 ? "" : "s"
  } found</p>
      <ul class="items">${itemsHtml}</ul>
      ${showMoreHtml}
    </section>`;
}

function renderPage({ q, page, totalPages, groups, expand, groupLimit }) {
  const groupsHtml = groups
    .map((group) => renderGroup({ q, page, expand, groupLimit, group }))
    .join("");

  const prevHref = buildUrl({ q, page: page - 1, expand });
  const nextHref = buildUrl({ q, page: page + 1, expand });

  const prevHtml =
    page > 1
      ? `<a data-testid="prev-page" href="${escapeHtml(
          prevHref
        )}" class="page-link">&laquo; Previous</a>`
      : `<span data-testid="prev-page" class="page-link disabled">&laquo; Previous</span>`;

  const nextHtml =
    page < totalPages
      ? `<a data-testid="next-page" href="${escapeHtml(
          nextHref
        )}" class="page-link">Next &raquo;</a>`
      : `<span data-testid="next-page" class="page-link disabled">Next &raquo;</span>`;

  const emptyStateHtml =
    groups.length === 0
      ? `<p class="empty-state">No products matched your search.</p>`
      : "";

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Storefront Search</title>
<style>
  :root { color-scheme: light; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
    color: #1a1a1a;
    background: #fafafa;
  }
  h1 { font-size: 1.5rem; }
  form.search-form {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
  }
  input[data-testid="search-input"] {
    flex: 1;
    padding: 0.5rem 0.75rem;
    font-size: 1rem;
    border: 1px solid #ccc;
    border-radius: 6px;
  }
  form.search-form button {
    padding: 0.5rem 1rem;
    font-size: 1rem;
    border: none;
    border-radius: 6px;
    background: #2563eb;
    color: white;
    cursor: pointer;
  }
  .group {
    background: white;
    border: 1px solid #e5e5e5;
    border-radius: 8px;
    padding: 1rem 1.25rem;
    margin-bottom: 1rem;
  }
  .brand-name { margin: 0 0 0.15rem 0; font-size: 1.2rem; }
  .brand-total { margin: 0 0 0.75rem 0; color: #555; font-size: 0.9rem; }
  ul.items { list-style: none; margin: 0; padding: 0; }
  li.item {
    display: flex;
    justify-content: space-between;
    padding: 0.4rem 0;
    border-top: 1px solid #f0f0f0;
  }
  li.item:first-child { border-top: none; }
  .item-name { font-weight: 500; }
  .item-meta { color: #777; font-size: 0.85rem; }
  a.show-more {
    display: inline-block;
    margin-top: 0.6rem;
    font-size: 0.9rem;
    color: #2563eb;
    text-decoration: none;
  }
  a.show-more:hover { text-decoration: underline; }
  nav.pagination {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    margin-top: 1.5rem;
  }
  .page-link { color: #2563eb; text-decoration: none; }
  .page-link.disabled { color: #aaa; pointer-events: none; }
  .empty-state { color: #777; font-style: italic; }
</style>
</head>
<body>
  <h1>Product Search</h1>
  <form class="search-form" method="GET" action="/" data-testid="search-form">
    <input
      type="text"
      name="q"
      value="${escapeHtml(q)}"
      data-testid="search-input"
      placeholder="Search products..."
      autocomplete="off"
    />
    <button type="submit">Search</button>
  </form>

  <div class="groups">
    ${groupsHtml}
    ${emptyStateHtml}
  </div>

  <nav class="pagination">
    ${prevHtml}
    <span data-testid="page-indicator">Page ${page} of ${totalPages}</span>
    ${nextHtml}
  </nav>
</body>
</html>`;
}

module.exports = { renderPage, buildUrl, escapeHtml };

"use strict";

const express = require("express");
const {
  ensureCollectionAndData,
  groupedSearch,
  fetchAllForBrand,
} = require("./lib/typesense");
const { renderPage } = require("./lib/render");

const PORT = process.env.PORT || 3000;
const HOST = "0.0.0.0";

const GROUP_LIMIT = 3; // max items shown per brand group before "show more"
const GROUPS_PER_PAGE = 3; // max brand groups per page

const app = express();

function parseExpand(raw) {
  if (!raw) return [];
  const arr = Array.isArray(raw) ? raw : [raw];
  return [...new Set(arr.map(String).filter(Boolean))];
}

app.get("/", async (req, res) => {
  try {
    const q = typeof req.query.q === "string" ? req.query.q : "";
    let page = parseInt(req.query.page, 10);
    if (!Number.isFinite(page) || page < 1) page = 1;
    const expand = parseExpand(req.query.expand);

    let { totalGroups, groups } = await groupedSearch({
      q,
      page,
      groupLimit: GROUP_LIMIT,
      groupsPerPage: GROUPS_PER_PAGE,
    });

    let totalPages = Math.max(1, Math.ceil(totalGroups / GROUPS_PER_PAGE));

    // Clamp out-of-range page requests and re-fetch.
    if (page > totalPages) {
      page = totalPages;
      ({ totalGroups, groups } = await groupedSearch({
        q,
        page,
        groupLimit: GROUP_LIMIT,
        groupsPerPage: GROUPS_PER_PAGE,
      }));
      totalPages = Math.max(1, Math.ceil(totalGroups / GROUPS_PER_PAGE));
    }

    // For any expanded brand on this page, fetch the full item list.
    for (const group of groups) {
      if (expand.includes(group.brand) && group.total > GROUP_LIMIT) {
        group.items = await fetchAllForBrand({ q, brand: group.brand });
      }
    }

    const html = renderPage({
      q,
      page,
      totalPages,
      groups,
      expand,
      groupLimit: GROUP_LIMIT,
    });

    res.set("Content-Type", "text/html; charset=utf-8");
    res.send(html);
  } catch (err) {
    console.error(err);
    res.status(500).send("Internal Server Error: " + err.message);
  }
});

async function start() {
  console.log("Connecting to Typesense and ensuring dataset is loaded...");
  await ensureCollectionAndData();
  console.log("Dataset ready.");

  app.listen(PORT, HOST, () => {
    console.log(`Server listening on http://${HOST}:${PORT}`);
  });
}

start().catch((err) => {
  console.error("Failed to start server:", err);
  process.exit(1);
});
